// SPDX-License-Identifier: GPL-3.0-only
// Usina - VAPOR: the 2014 granular texture processor, from Emilie Gillet's module (MIT) with the six modes of Matthias
// Puech's alternative firmware (MIT; the port in src/fx/clouds, generated by tools/port/port_clouds.py and checked
// bit for bit against upstream). This class is what the module's main file and CV scaler (clouds.cc, cv_scaler.cc)
// are around that code, played the module's way:
//   - at its own rate, 32 kHz, in its codec's blocks of 32 samples, behind a sample-rate converter
//     (src/dsp/Resampler.h) standing where the codec's filters stand (none when the host runs at 32 kHz);
//   - its knobs smoothed once a block with the module's own coefficients, PITCH through its quantized law (the
//     semitones and octaves held), DRY/WET through its (x 1.05 - 0.025);
//   - its input as the codec gives it (16 bits: the host's full scale is the codec's), its output soft-limited as the
//     processor makes it;
//   - its background work (the splice search, the spectral frames: the module's main loop) between the blocks.
// The module's blend knob (one knob, four parameters) is four knobs here; its TRIG input is fed by the notes played
// or the host's beats; its FREEZE and REVERSE are buttons. Ours, around it: the switch on/off, faded, and a fade
// around a mode or quality change (the processor restarts silent there, as the module does).
//
// The knobs stay in the module's own range, 0 .. 65535/65536 (its converter's): at exactly 1 its table lookups
// read one value past their tables (measured 22/10 with the address sanitizer, tools/port/check_clouds.sh).
//
// Latency: the converters' and one block (latencySamples(); about 3 ms at 48 kHz). Not reported to the host yet, as
// the texture's (docs/BACKLOG.md: a minimum-phase converter and a fixed report are queued). No allocation in
// process(); prepare() sizes everything.
#pragma once
#include <memory>

namespace usina::fx {

class Vapor {
public:
    enum Mode { kGranular = 0, kStretch, kLoopingDelay, kSpectral, kReverb, kResonator, kNumModes };   // (the module's)
    enum Quality { kStereo16 = 0, kMono16, kStereo8, kMono8, kNumQualities };   // (the module's: 8 bits at half rate)

    // the panel, as knob positions 0..1 (the module's laws make them its values)
    struct Knobs {
        float position = 0.5f, size = 0.5f, pitch = 0.5f, density = 0.5f, texture = 0.5f;   // (pitch: 0.5 = unison)
        float dryWet = 0.5f, spread = 0.0f, feedback = 0.0f, reverb = 0.0f;
        bool freeze = false, reverse = false;
        int mode = kGranular, quality = kStereo16;
    };

    Vapor();
    ~Vapor();

    void prepare(double hostRate, int maxBlock);         // (allocates: never on the audio thread)
    void reset();                                        // silent, emptied, as prepared
    // in place; gate: the TRIG input at the host's rate (a note held, a beat), or nullptr. on: the switch - turned
    // off, it fades out (20 ms) and stops; turned on, it starts empty and fades in
    void process(float* l, float* r, int n, const Knobs& k, const bool* gate, bool on);
    bool active() const;
    int latencySamples() const;                          // host samples

    static const char* modeName(int m);
    static const char* qualityName(int q);
    // what each knob does in a mode (the module's own mapping: granular_processor.cc), for the panel's captions
    enum Knob { kPosition = 0, kSize, kPitch, kDensity, kTexture, kDryWet, kSpread, kFeedback, kReverbKnob, kNumKnobs };
    static const char* knobName(int mode, int knob);
    static float pitchSemitones(float knob);             // PITCH's law (the module's quantized table), for its text

    struct Impl;

private:
    std::unique_ptr<Impl> impl;
};

} // namespace usina::fx
